contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry used by the checker
    function run(uint256 withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // Ensure the test contract has enough Ether to fund any deposit calls if needed.
        // (Not strictly required here, but safe.)
        require(address(this).balance >= 0);

        // Observe contract and tester balances before the call
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;

        // Attempt withdraw and record whether it reverted.
        bool reverted;
        c.withdraw(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe balances after the call
        uint256 afterContractBalance = address(c).balance;
        uint256 afterThisBalance = address(this).balance;

        // If withdraw did not revert, the contract's Ether balance must have decreased by exactly withdrawAmount
        // and this contract's balance must have increased by exactly withdrawAmount.
        // If it reverted, no further requirement.
        assert(
            reverted || (
                beforeContractBalance >= afterContractBalance &&
                afterThisBalance >= beforeThisBalance &&
                (beforeContractBalance - afterContractBalance) == withdrawAmount &&
                (afterThisBalance - beforeThisBalance) == withdrawAmount
            )
        );
    }

    // allow receiving Ether when c.transfer sends Ether to this contract
    receive() external payable {}
}

