// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 withdrawAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterContractBalance = address(c).balance;
        uint256 afterThisBalance = address(this).balance;
        assertTrue(reverted || (
                beforeContractBalance >= afterContractBalance &&
                afterThisBalance >= beforeThisBalance &&
                (beforeContractBalance - afterContractBalance) == withdrawAmount &&
                (afterThisBalance - beforeThisBalance) == withdrawAmount
            ));
    }

    function testFuzz_run(uint256 withdrawAmount) public {
        _run(withdrawAmount);
    }

    receive() external payable {}
}
